53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const CURSE_SURCHARGE = 0.5;
60	
61	const HIGH_ENCHANTMENT_LEVEL = 5;
62	
63	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
64	
65	const LOYALTY_YEARS = 2;
66	
67	const LOYALTY_DISCOUNT = 0.2;
68	
69	const BASE_PREMIUMS: Record<string, number> = {
70	  sword: 100,
71	  amulet: 60,
72	  staff: 80,
73	  potion: 40,
74	  rune: 25,
75	  moonstone: 25,
76	};
77	
78	const BLOCK_SIZE = 3;
79	
80	const BLOCK_BASE_PREMIUM = 60;
81	
82	const countsByType = (items: Item[]): Map<string, number> => {
83	  const counts = new Map<string, number>();
84	
85	  for (const item of items) {
86	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
87	  }
88	
89	  return counts;
90	};
91	
92	const groupBasePremium = (type: string, count: number): number =>
93	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
94	
95	const policyBasePremium = (items: Item[]): number =>
96	  [...countsByType(items)].reduce(
97	    (total, [type, count]) => total + groupBasePremium(type, count),
98	    0,
99	  );
100	
101	// Modifiers below all express a rate applied to some base. Keep every one of
102	// them in the form `base + base * RATE`. The algebraically equivalent
103	// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
104	// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
105	// upward float error rather than absorbing it.
106	
107	// Item-specific modifiers: each is computed on the affected item's OWN base
108	// premium, then summed across items. Note this is the item's UNIT base premium
109	// — never the block-adjusted one. A rune inside a block of 3 is still
110	// surcharged on its own 25 G, not on its 20 G share of the block.
111	const unitBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
112	
113	const isHighlyEnchanted = (item: Item): boolean =>
114	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
115	
116	const itemSurchargeRate = (item: Item): number =>
117	  (item.cursed ? CURSE_SURCHARGE : 0) +
118	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
119	
120	const itemSurcharges = (items: Item[]): number =>
121	  items.reduce(
122	    (total, item) => total + unitBasePremium(item) * itemSurchargeRate(item),
123	    0,
124	  );
125	
126	// Policy-wide modifiers: each is computed on the policy base premium (the sum
127	// of all item base premiums), independent of which items make it up.
128	const isLoyal = (customer: Customer): boolean =>
129	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
130	
131	const policyModifierRate = (customer: Customer): number =>
132	  FIRST_INSURANCE_SURCHARGE - (isLoyal(customer) ? LOYALTY_DISCOUNT : 0);
133	
134	const quote = (items: Item[], customer: Customer): QuoteResult => {
135	  const policyBase = policyBasePremium(items);
136	
137	  return {
138	    premium: Math.ceil(
139	      policyBase +
140	        itemSurcharges(items) +
141	        policyBase * policyModifierRate(customer) +
142	        PROCESSING_FEE,
143	    ),
144	  };
145	};
146	
147	const runStep = (step: Step, customer: Customer): StepResult => {
148	  if (step.op === "quote") return quote(step.items, customer);
149	
150	  throw new Error(`Unsupported step: ${step.op}`);
151	};
152	
153	export const runScenario = (scenario: Scenario): ScenarioResult => ({
154	  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
155	});
